from rdkit import Chem
mol = Chem.MolFromSmiles('N#CC1CCc2[nH]c3ccccc3c2C1')
if mol:
    print('Molecular formula:', Chem.rdMolDescriptors.CalcMolFormula(mol))
    print('Num atoms:', mol.GetNumAtoms())
    print('Num rings:', mol.GetRingInfo().NumRings())
    for atom in mol.GetAtoms():
        if atom.GetAtomicNum() == 7:  # Nitrogen
            print(f'Nitrogen {atom.GetIdx()}: hybridization={atom.GetHybridization()}, neighbors={[n.GetIdx() for n in atom.GetNeighbors()]}')
    # Find the cyano carbon
    for bond in mol.GetBonds():
        if bond.GetBeginAtom().GetAtomicNum() == 6 and bond.GetEndAtom().GetAtomicNum() == 6:
            if bond.GetBondType() == Chem.BondType.TRIPLE:
                print(f'Triple bond between {bond.GetBeginAtom().GetIdx()} and {bond.GetEndAtom().GetIdx()}')
"
"}

